impl Plan<'_,'_>{fn list(&mut self,v:&Value,variant:&str)->Result<(),String>{let items=array(v,"items")?;let n=items.len();let bw=self.s.w-2.0*self.s.margin;let mx=self.s.margin;let cx=self.s.w/2.0;let top=self.s.top;let takeaway=v.get("takeaway").filter(|v|!v.is_null());let bot=self.s.bottom-if takeaway.is_some(){84.0}else{0.0};if let Some(tk)=takeaway{let fs=crate::typography::fit_one_line(label(tk,"label"),&self.s.theme,30.0,22.0,bw-88.0);let w=bw.min(self.width(label(tk,"label"),fs)+64.0);self.add("takeaway",(cx-w/2.0,self.s.bottom-64.0,w,64.0),tk,"item",json!({"fs":fs,"lh":fs+6.0}));}
 if variant=="spotlight"{let top0=if label(v,"title").is_empty(){top-52.0}else{top-4.0};let room=bot-top0;let(railw,win,ry,px,pw,ph,py)=if self.s.tall{let ph=(room*0.56).round().min((bw*0.8).round());let rr=bot-(top0+ph+28.0);let win=(n as f64).min(((rr+12.0)/76.0).floor()).min(3.0).max(2.0) as usize;(bw,win,top0+ph+28.0+(rr-(win as f64*64.0+(win-1) as f64*12.0))/2.0,mx,bw,ph,top0)}else{let win=(n as f64).min(((room+12.0)/76.0).floor()).min(5.0).max(2.0) as usize;let px=mx+420.0;let pw=self.s.w-mx-px;let ph=room.min((pw*0.74).round());(380.0,win,top0+(room-(win as f64*64.0+(win-1) as f64*12.0))/2.0,px,pw,ph,top0+(room-ph)/2.0)};let fs=items.iter().map(|it|crate::typography::fit_one_line(label(it,"label"),&self.s.theme,26.0,22.0,railw-110.0)).fold(26.0_f64,f64::min);let timed=items.iter().all(|it|it["at"].as_f64().is_some());for(i,it)in items.iter().enumerate(){let mut extra=json!({"fs":fs,"lh":(fs*1.12).round(),"rail":1});let slot=i.min(win-1);if timed&&n>win{let slides:Vec<Value>=((i+1).max(win)..n.min(i+win)).map(|q|json!({"t":num(&items[q],"at")-num(v,"start"),"dy":-76})).collect();if !slides.is_empty(){extra["slides"]=json!(slides)}if i+win<n{extra["goneAt"]=items[i+win]["at"].clone()}if i>=win{extra["fixA"]=json!(num(it,"at")-num(v,"start")+0.22)}}self.add("railRow",(mx,ry+slot as f64*76.0,railw,64.0),&json!({"label":it["label"],"icon":it["icon"],"at":it["at"],"brand":it["brand"]}),"item",extra);}
 let mut stage=items.clone();if let Some(intro)=v.get("intro"){if !intro.is_null()&&items.first().is_some_and(|it|it["at"].as_f64().is_some()){stage.insert(0,json!({"label":intro.get("label").cloned().unwrap_or(json!("")),"icon":"","at":num(v,"start")+0.3,"picture":intro["picture"],"intro":1}));}}for(i,it)in stage.iter().enumerate(){let gone=stage.get(i+1).and_then(|it|it["at"].as_f64());let ex=gone.map(|t|json!({"goneAt":t})).unwrap_or(json!({}));if it["picture"].is_null(){self.add("spotCard",(px,py,pw,ph),it,"item",ex);continue}let lfs=if label(it,"label").is_empty(){0.0}else{crate::typography::fit_one_line(label(it,"label"),&self.s.theme,32.0,20.0,pw-120.0)};let lh=if lfs==0.0{0.0}else{(lfs*2.4).round()};let n0=self.nodes.len();let e0=self.edges.len();self.add("spotPanel",(px,py,pw,ph),&json!({"at":it["at"],"tone":it["tone"]}),"item",ex.clone());let(w,up)=picture_size(&it["picture"],pw-24.0,ph-lh-28.0);let h=w*if up{640.0/400.0}else{400.0/640.0};self.picture(&json!({"picture":it["picture"],"start":v["start"],"end":v["end"]}),px+(pw-w)/2.0,py+18.0+((ph-lh-28.0-h)/2.0).max(0.0),w,up)?;let end=self.nodes.len();if lfs>0.0{let mut ex=ex;ex["at"]=it["at"].clone();ex["tone"]=it["tone"].clone();self.text("spotLabel",label(it,"label"),(px+20.0,py+ph-lh-10.0,pw-40.0,lh),"item",lfs,(lfs*1.15).round(),"center",ex);}let t0=it["at"].as_f64().map(|t|t-num(v,"start")+0.2);for q in n0+1..end{let node=&mut self.nodes[q].item;if let Some(t)=t0{node["fixA"]=json!(num(node,"fixA").max(t+0.12*(q-n0) as f64));}if let Some(t)=gone{node["goneAt"]=json!(t)}}for edge in &mut self.edges[e0..]{if let Some(t)=t0{edge.extra["fixA"]=json!(num(&edge.extra,"fixA").max(t+0.5));}if let Some(t)=gone{edge.extra["gone"]=json!(edge.extra["gone"].as_f64().unwrap_or(1e9).min(t-num(v,"start")));}}}return Ok(())}
 if variant=="cards"{let ctop=if label(v,"title").is_empty(){top-48.0}else{top};if self.s.tall&&n>1{let rows=n.div_ceil(2);let w=(bw-28.0)/2.0;let h=(w*0.9).round().min(((bot-ctop-28.0*(rows-1) as f64)/rows as f64).floor());let y=(ctop+bot)/2.0-(rows as f64*h+(rows-1) as f64*28.0)/2.0;for(i,it)in items.iter().enumerate(){let r=i/2;let nr=2.min(n-r*2);self.add("cardTile",(cx-(nr as f64*w+(nr-1) as f64*28.0)/2.0+(i%2) as f64*(w+28.0),y+r as f64*(h+28.0),w,h),it,"item",json!({}));}}else{let w=380.0_f64.min((bw-40.0*(n-1) as f64)/n as f64);let h=(w*0.86).round().min(bot-top+20.0);let y=(ctop+bot)/2.0-h/2.0-6.0;for(i,it)in items.iter().enumerate(){self.add("cardTile",(cx-(n as f64*w+(n-1) as f64*40.0)/2.0+i as f64*(w+40.0),y,w,h),it,"item",json!({}));}}return Ok(())}
 if !matches!(variant,"bullets"|"checklist"|"warnings"){return Err(format!("unknown list variant {variant}"))}let timed=items.iter().all(|it|it["at"].as_f64().is_some());let per=if timed&&n>5{n.div_ceil(n.div_ceil(4))}else{n};let pages:Vec<&[Value]>=items.chunks(per).collect();let count=pages.iter().map(|p|p.len()).max().unwrap_or(1);let mut fs:f64=if count<=3{36.0}else if count<=4{32.0}else if count<=6{28.0}else{24.0};let mut rh:f64=if count<=3{88.0}else if count<=4{76.0}else if count==5{62.0}else if count==6{56.0}else{46.0};let gap=if count<=3{20.0}else if count<=4{16.0}else if count<=6{10.0}else{6.0};if takeaway.is_some(){rh=rh.min(((bot-top+40.0-(count-1) as f64*gap)/count as f64).floor());fs=fs.min((rh*0.5).round())}let ms=(rh*0.62).round();let longest=items.iter().map(|it|self.width(label(it,"label"),fs)).fold(0.0_f64,f64::max);let w=bw.min(420.0_f64.max(ms+24.0+longest+16.0));let top=if label(v,"title").is_empty(){top-48.0}else{top};for(k,page)in pages.iter().enumerate(){let y=(top+bot)/2.0-(page.len() as f64*rh+(page.len()-1) as f64*gap)/2.0;for(i,it)in page.iter().enumerate(){let mut ex=json!({"fs":fs,"marker":if variant=="checklist"{"check"}else if variant=="warnings"{"cross"}else{"dot"},"ms":ms});if let Some(next)=pages.get(k+1){ex["goneAt"]=json!(num(&next[0],"at")-0.15);}self.add("listRow",(cx-w/2.0,y+i as f64*(rh+gap),w,rh),&json!({"label":it["label"],"icon":"","at":it["at"],"tone":it["tone"]}),"item",ex);}}Ok(())}}
